import sys
from functools import lru_cache
sys.setrecursionlimit(10000)

@lru_cache(maxsize=None)
def drogi(i, j):                # liczba ścieżek w siatce w prawo/w dół
    if i == 0 or j == 0:
        return 1
    return drogi(i - 1, j) + drogi(i, j - 1)

print(drogi(16, 16))            # 601080390

