using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;
    set<long long> rozne(a.begin(), a.end());
    priority_queue<long long, vector<long long>, greater<long long>> h;  // min-heap jak heapq
    for (long long x : a) {
        h.push(x);
        if (h.size() > 3) h.pop();
    }
    long long suma = 0;
    while (!h.empty()) {
        suma += h.top();
        h.pop();
    }
    cout << rozne.size() << ' ' << suma << '\n';
}

